#!/usr/bin/env bash
# TD-85 · Feb-2026 — narrower session-hygiene precheck.
#
# The naive ``git status --short | wc -l == 0`` guard set by the
# TD-61 discipline cannot be met on the Expo pod: the working tree
# always carries ~1,900 "unauthored" paths from parallel sessions
# and transient tool caches (``.pyc`` compilation, ``.ruff_cache``,
# ``.metro-cache``, ``mobile/.expo/types/router.d.ts`` regenerated by
# the Expo CLI, ``mobile/artifacts/offline-mode-verification.txt``
# rewritten by Jest, three ``.env.example`` files published by the
# platform at pod boot, ``.pytest_cache``).
#
# This script runs a NARROWER precheck that:
#
#   * Excludes every known noise path listed above (see
#     ``NOISE_PATTERNS`` below).
#   * Reports the remaining "material drift" count.
#   * Exits 0 if the material drift count is 0 (session hygiene
#     clean), exit 1 otherwise.
#   * On exit 1, prints the material-drift paths so the operator /
#     agent can decide whether to stash, commit, or revert them.
#
# Agent usage:
#
#     ./scripts/td85_session_hygiene_precheck.sh \
#       || { echo "material drift — stash before committing"; exit 1; }
#
# The ``--only -- <paths>`` discipline on commits remains the
# load-bearing guard; this precheck is the detector that would
# surface a stray file the agent authored before an atomic commit.

set -u

cd "$(dirname "$0")/.."

NOISE_PATTERNS=(
  # Python bytecode caches
  '__pycache__/'
  '\.pyc$'
  # Lint / type cache DBs
  '\.ruff_cache/'
  '\.pytest_cache/'
  '\.mypy_cache/'
  # Expo + Metro caches
  'mobile/\.expo/'
  'mobile/\.metro-cache/'
  # Platform-published env templates (never agent-authored)
  'backend/\.env\.example$'
  'frontend/\.env\.example$'
  'mobile/\.env\.example$'
  # Jest artifact rewritten on every mobile test run
  'mobile/artifacts/offline-mode-verification\.txt$'
  # Yarn integrity files
  '\.yarn-integrity$'
  # Node build output
  'frontend/build/'
  'frontend/node_modules/'
  'mobile/node_modules/'
)

RAW_STATUS=$(git status --short 2>/dev/null)
if [ -z "$RAW_STATUS" ]; then
  echo "[td85-precheck] working tree is strictly clean (no drift at all)."
  exit 0
fi

# Build a single regex alternation from the noise patterns.
NOISE_RE=$(IFS='|'; echo "${NOISE_PATTERNS[*]}")

# Each line of ``git status --short`` is ``XY path`` where path
# starts at column 4. Strip the status prefix before matching.
MATERIAL=$(echo "$RAW_STATUS" \
  | sed -E 's|^.{3}||' \
  | grep -Ev "$NOISE_RE" \
  || true)

NOISE_COUNT=$(echo "$RAW_STATUS" | wc -l)
MATERIAL_COUNT=$(echo "$MATERIAL" | grep -c '[^[:space:]]' || true)

echo "[td85-precheck] raw status rows:      $NOISE_COUNT"
echo "[td85-precheck] material-drift rows:  $MATERIAL_COUNT"

if [ "$MATERIAL_COUNT" -eq 0 ]; then
  echo "[td85-precheck] session hygiene CLEAN (all drift is known noise)."
  exit 0
fi

echo
echo "[td85-precheck] MATERIAL DRIFT present — review before committing:"
echo "$MATERIAL" | sed 's|^|  |'
exit 1
